import Foundation

enum L10n {
    private static let preferencesKey = "payjoy.app.preferences"
    static let defaultProfileNicknameKey = "打工人小开"
    static let defaultProfileMottoKey = "上班赚钱，下班花钱，努力生活，开心开薪！"

    static var currentLanguage: AppLanguage {
        storedLanguage.resolved
    }

    static var currentMarket: AppMarket {
        storedPreferences?.resolvedMarket ?? .systemResolved
    }

    static var appDisplayName: String {
        switch currentLanguage {
        case .zhHant: "開薪"
        case .en: "ClockJoy"
        case .ja, .ko: "ClockJoy"
        case .system, .zhHans: "开薪"
        }
    }

    static func t(_ key: String) -> String {
        let language = currentLanguage
        let value: String
        if let marketValue = traditionalMarketOverrides[currentMarket]?[key] {
            value = marketValue
        } else if let closingValue = closingReceiptTranslations[language]?[key] {
            value = closingValue
        } else if let paydayValue = paydayExperienceTranslations[language]?[key] {
            value = paydayValue
        } else if let wishValue = wishExperienceTranslations[language]?[key] {
            value = wishValue
        } else if let growthValue = growthExperienceTranslations[language]?[key] {
            value = growthValue
        } else if let coreValue = coreExperienceTranslations[language]?[key] {
            value = coreValue
        } else if language == .system || language == .zhHans {
            value = key
        } else {
            value = proSalaryReportTable[language]?[key]
                ?? qualitySupplementalTable[language]?[key]
                ?? finalSupplementalTable[language]?[key]
                ?? table[language]?[key]
                ?? supplementalTable[language]?[key]
                ?? patternTranslation(key, language: language)
                ?? fallbackTranslation(key, language: language)
                ?? key
        }
        return replacingRetiredOverseasBrand(in: value, language: language)
    }

    static func t(_ key: String, _ value: String) -> String {
        String(format: t(key), locale: Locale(identifier: currentLanguage.localeIdentifier), value)
    }

    static func format(_ key: String, _ arguments: CVarArg...) -> String {
        String(format: t(key), locale: Locale(identifier: currentLanguage.localeIdentifier), arguments: arguments)
    }

    #if DEBUG
    static func untranslatedKeys(_ keys: [String], language: AppLanguage) -> [String] {
        keys.filter { !hasTranslationMapping(for: $0, language: language) }
    }

    private static func hasTranslationMapping(for key: String, language: AppLanguage) -> Bool {
        if language == .system || language == .zhHans {
            return true
        }
        return wishExperienceTranslations[language]?[key] != nil
            || closingReceiptTranslations[language]?[key] != nil
            || paydayExperienceTranslations[language]?[key] != nil
            || growthExperienceTranslations[language]?[key] != nil
            || coreExperienceTranslations[language]?[key] != nil
            || proSalaryReportTable[language]?[key] != nil
            || qualitySupplementalTable[language]?[key] != nil
            || finalSupplementalTable[language]?[key] != nil
            || table[language]?[key] != nil
            || supplementalTable[language]?[key] != nil
            || patternTranslation(key, language: language) != nil
            || fallbackTranslation(key, language: language) != nil
    }
    #endif

    private static var storedLanguage: AppLanguage {
        #if DEBUG
        if ProcessInfo.processInfo.environment["PAYJOY_SCREENSHOT_MODE"] == "1",
           let screenshotLanguage = ProcessInfo.processInfo.environment["PAYJOY_SCREENSHOT_LANGUAGE"]
                .flatMap(AppLanguage.init(rawValue:)) {
            return screenshotLanguage
        }
        #endif
        return storedPreferences?.appLanguage ?? .system
    }

