    private static var storedPreferences: AppPreferences? {
        if let data = UserDefaults.standard.data(forKey: preferencesKey),
           let preferences = try? JSONDecoder().decode(AppPreferences.self, from: data) {
            return preferences
        }
        if let data = UserDefaults(suiteName: AppConstants.appGroupIdentifier)?.data(forKey: preferencesKey),
           let preferences = try? JSONDecoder().decode(AppPreferences.self, from: data) {
            return preferences
        }
        return nil
    }

    private static func replacingRetiredOverseasBrand(
        in value: String,
        language: AppLanguage
    ) -> String {
        let normalizedValue = value.replacingOccurrences(of: "PayJoy", with: "ClockJoy")
        switch language {
        case .zhHant:
            return normalizedValue.replacingOccurrences(of: "ClockJoy", with: "開薪")
        case .en:
            return normalizedValue
                .replacingOccurrences(of: "ClockJoy Worker", with: "ClockJoy Buddy")
        case .ja, .ko:
            return normalizedValue
        case .system, .zhHans:
            return normalizedValue.replacingOccurrences(of: "ClockJoy", with: "开薪")
        }
    }

