    private static func patternTranslation(_ key: String, language: AppLanguage) -> String? {
        if key.hasPrefix("已安排 "), key.contains(" 开薪、"), key.hasSuffix(" 到账提醒。") {
            let text = key
                .replacingOccurrences(of: "已安排 ", with: "")
                .replacingOccurrences(of: " 到账提醒。", with: "")
            let parts = text.components(separatedBy: " 开薪、")
            guard parts.count == 2,
                  let scheduleEnd = parts[0].lastIndex(of: " ") else { return nil }
            let workdays = String(parts[0][..<scheduleEnd])
            let start = String(parts[0][parts[0].index(after: scheduleEnd)...])
            switch language {
            case .zhHant: return "已安排 \(traditionalized(workdays)) \(start) 開薪、\(parts[1]) 入帳提醒。"
            case .en: return "Scheduled \(workdays) reminders: start at \(start), clock-out at \(parts[1])."
            case .ja: return "\(workdays)の通知を設定しました：開始 \(start)、退勤 \(parts[1])。"
            case .ko: return "\(workdays) 알림을 예약했습니다: 시작 \(start), 퇴근 \(parts[1])."
            default: return nil
            }
        }
        if key.hasPrefix("计薪日："), key.hasSuffix("。未选中日期可在首页临时开启加班计薪。") {
            let value = key
                .replacingOccurrences(of: "计薪日：", with: "")
                .replacingOccurrences(of: "。未选中日期可在首页临时开启加班计薪。", with: "")
            switch language {
            case .zhHant:
                return "計薪日：\(traditionalized(value))。未選中的日期可在首頁臨時開啟加班計薪。"
            case .en:
                return "Paid days: \(value). Unselected days can be counted as overtime from Home."
            case .ja:
                return "支給対象日：\(value)。未選択の日はホームで一時的に残業扱いにできます。"
            case .ko:
                return "급여 계산일: \(value). 선택하지 않은 날짜는 홈에서 임시로 초과근무 계산을 켤 수 있습니다."
            case .system, .zhHans:
                return nil
            }
        }

        if let value = key.removingSuffix("已赚") {
            return localizedPeriodPhrase(period: value, zhHantSuffix: "已賺", enSuffix: "Earned", jaSuffix: "の収入", koSuffix: " 번 금액", language: language)
        }
        if let value = key.removingSuffix("进度") {
            return localizedPeriodPhrase(period: value, zhHantSuffix: "進度", enSuffix: "Progress", jaSuffix: "の進捗", koSuffix: " 진행률", language: language)
        }
        if key.hasPrefix("预计 ") {
            let amount = key.replacingOccurrences(of: "预计 ", with: "")
            switch language {
            case .zhHant: return "預估 \(amount)"
            case .en: return "Projected \(amount)"
            case .ja: return "予想 \(amount)"
            case .ko: return "예상 \(amount)"
            default: return nil
            }
        }
        if key.hasPrefix("距离"), key.hasSuffix("目标还差") {
            let value = key
                .replacingOccurrences(of: "距离", with: "")
                .replacingOccurrences(of: "目标还差", with: "")
            switch language {
            case .zhHant: return "距離\(traditionalized(value))目標還差"
            case .en: return "Left to \(periodName(value, language: .en)) goal"
            case .ja: return "\(periodName(value, language: .ja))の目標まで"
            case .ko: return "\(periodName(value, language: .ko)) 목표까지"
            default: return nil
            }
        }
        if key.hasSuffix("目标达成！") {
            let value = key.replacingOccurrences(of: "目标达成！", with: "")
            switch language {
            case .zhHant: return "\(traditionalized(value))目標達成！"
            case .en: return "\(periodName(value, language: .en)) goal reached!"
            case .ja: return "\(periodName(value, language: .ja))の目標達成！"
            case .ko: return "\(periodName(value, language: .ko)) 목표 달성!"
            default: return nil
            }
        }
        if key.hasSuffix("目标已达成，今天可以放心开心一下。") {
            let value = key.replacingOccurrences(of: "目标已达成，今天可以放心开心一下。", with: "")
            switch language {
            case .zhHant: return "\(traditionalized(value))目標已達成，今天可以放心開心一下。"
            case .en: return "\(periodName(value, language: .en)) goal reached. Enjoy today."
            case .ja: return "\(periodName(value, language: .ja))の目標達成。今日は安心して楽しめます。"
            case .ko: return "\(periodName(value, language: .ko)) 목표를 달성했습니다. 오늘은 마음 편히 즐기세요."
            default: return nil
            }
        }
        if key.hasPrefix("还剩"), key.hasSuffix("个工作日，稳住！") {
            let value = key
                .replacingOccurrences(of: "还剩 ", with: "")
                .replacingOccurrences(of: " 个工作日，稳住！", with: "")
            switch language {
            case .zhHant: return "還剩 \(value) 個工作日，穩住！"
            case .en: return "\(value) workdays left. Keep steady!"
            case .ja: return "残り \(value) 営業日、落ち着いて！"
            case .ko: return "\(value) 근무일 남았습니다. 침착하게!"
            default: return nil
            }
        }
        if key.hasSuffix("工作日已结束，看看目标完成情况。") {
            let value = key.replacingOccurrences(of: "工作日已结束，看看目标完成情况。", with: "")
            switch language {
            case .zhHant: return "\(traditionalized(value))工作日已結束，看看目標完成情況。"
            case .en: return "\(periodName(value, language: .en)) workdays are over. Check your goal progress."
            case .ja: return "\(periodName(value, language: .ja))の勤務日は終了。目標の進捗を確認しましょう。"
            case .ko: return "\(periodName(value, language: .ko)) 근무일이 끝났습니다. 목표 진행률을 확인하세요."
            default: return nil
            }
        }
        if key.hasSuffix("只剩 1 个工作日，今天冲刺一下。") {
            let value = key.replacingOccurrences(of: "只剩 1 个工作日，今天冲刺一下。", with: "")
            switch language {
            case .zhHant: return "\(traditionalized(value))只剩 1 個工作日，今天衝刺一下。"
            case .en: return "Only 1 workday left in \(periodName(value, language: .en)). Push today."
            case .ja: return "\(periodName(value, language: .ja))は残り1営業日。今日はラストスパート。"
            case .ko: return "\(periodName(value, language: .ko)) 근무일이 1일 남았습니다. 오늘 힘내세요."
            default: return nil
            }
        }
        if key.contains("还剩 "), key.hasSuffix(" 个工作日，收尾阶段稳住。") || key.hasSuffix(" 个工作日，按节奏继续攒进度。") {
            let isFinalStage = key.hasSuffix(" 个工作日，收尾阶段稳住。")
            let marker = isFinalStage ? " 个工作日，收尾阶段稳住。" : " 个工作日，按节奏继续攒进度。"
            let parts = key.replacingOccurrences(of: marker, with: "").components(separatedBy: "还剩 ")
            guard parts.count == 2 else { return nil }
            switch language {
            case .zhHant:
                return "\(traditionalized(parts[0]))還剩 \(parts[1]) 個工作日，\(isFinalStage ? "收尾階段穩住。" : "按節奏繼續累積進度。")"
            case .en:
                let period = parts[0] == "本月" ? "this month" : parts[0] == "本年" ? "this year" : "in \(periodName(parts[0], language: .en))"
                return "\(parts[1]) workdays left \(period). \(isFinalStage ? "Stay steady for the finish." : "Keep building progress at your pace.")"
            case .ja:
                return "\(periodName(parts[0], language: .ja))は残り\(parts[1])営業日。\(isFinalStage ? "最後まで落ち着いて。" : "このペースで進めましょう。")"
            case .ko:
                return "\(periodName(parts[0], language: .ko)) 근무일이 \(parts[1])일 남았습니다. \(isFinalStage ? "마무리까지 침착하게 가세요." : "지금 리듬대로 진행하세요.")"
            default:
                return nil
            }
        }
        if key.contains("剩 "), key.hasSuffix(" 个工作日！") {
            let parts = key.replacingOccurrences(of: " 个工作日！", with: "").components(separatedBy: "剩 ")
            guard parts.count == 2 else { return nil }
            switch language {
            case .zhHant: return "\(traditionalized(parts[0]))剩 \(parts[1]) 個工作日！"
            case .en:
                let period = parts[0] == "本月" ? "this month" : parts[0] == "本年" ? "this year" : "in \(periodName(parts[0], language: .en))"
                return "\(parts[1]) workdays left \(period)!"
            case .ja: return "\(periodName(parts[0], language: .ja))は残り\(parts[1])営業日！"
            case .ko: return "\(periodName(parts[0], language: .ko)) 근무일 \(parts[1])일 남음!"
            default: return nil
            }
        }
        if key.hasSuffix("收官，看看战绩！") {
            let value = key.replacingOccurrences(of: "收官，看看战绩！", with: "")
            switch language {
            case .zhHant: return "\(traditionalized(value))收官，看看戰績！"
            case .en: return "\(periodName(value, language: .en)) wrap-up. Check the result!"
            case .ja: return "\(periodName(value, language: .ja))の締め。成果を見ましょう！"
            case .ko: return "\(periodName(value, language: .ko)) 마감입니다. 성과를 확인하세요!"
            default: return nil
            }
        }
        if key.hasSuffix(" 一次买断开通") {
            let price = key.replacingOccurrences(of: " 一次买断开通", with: "")
            switch language {
            case .zhHant: return "\(price) 一次買斷開通"
            case .en: return "Unlock forever for \(price)"
            case .ja: return "\(price) で買い切り解除"
            case .ko: return "\(price) 한 번 구매로 열기"
            default: return nil
            }
        }
        if key.hasSuffix(" 一次买断") {
            let price = key.replacingOccurrences(of: " 一次买断", with: "")
            switch language {
            case .zhHant: return "\(price) 一次買斷"
            case .en: return "\(price) one-time purchase"
            case .ja: return "\(price) 買い切り"
            case .ko: return "\(price) 한 번 구매"
            default: return nil
            }
        }
        if key.hasPrefix("当前主题 ") || key.hasPrefix("切换主题 ") || key.hasPrefix("当前 App 图标 ") || key.hasPrefix("切换 App 图标 ") {
            return controlAccessibilityTranslation(key, language: language)
        }
        if key.hasPrefix("已安排周一到周五 "), key.contains(" 开薪、"), key.hasSuffix(" 到账提醒。") {
            let text = key
                .replacingOccurrences(of: "已安排周一到周五 ", with: "")
                .replacingOccurrences(of: " 到账提醒。", with: "")
            let parts = text.components(separatedBy: " 开薪、")
            guard parts.count == 2 else { return nil }
            switch language {
            case .zhHant: return "已安排週一到週五 \(parts[0]) 開薪、\(parts[1]) 入帳提醒。"
            case .en: return "Scheduled weekday reminders: start at \(parts[0]), clock-out at \(parts[1])."
            case .ja: return "平日 \(parts[0]) の開始通知、\(parts[1]) の退勤通知を設定しました。"
            case .ko: return "평일 \(parts[0]) 시작, \(parts[1]) 퇴근 알림을 예약했습니다."
            default: return nil
            }
        }
        if key.hasPrefix("已安排 "), key.contains(" 午休开始、"), key.hasSuffix(" 午休结束提醒。") {
            let text = key
                .replacingOccurrences(of: "已安排 ", with: "")
                .replacingOccurrences(of: " 午休结束提醒。", with: "")
            let parts = text.components(separatedBy: " 午休开始、")
            guard parts.count == 2 else { return nil }
            switch language {
            case .zhHant: return "已安排 \(parts[0]) 午休開始、\(parts[1]) 午休結束提醒。"
            case .en: return "Scheduled lunch reminders: starts at \(parts[0]), ends at \(parts[1])."
            case .ja: return "昼休み通知を設定しました：開始 \(parts[0])、終了 \(parts[1])。"
            case .ko: return "점심 알림을 예약했습니다: 시작 \(parts[0]), 종료 \(parts[1])."
            default: return nil
            }
        }
        if key.hasPrefix("从 "), key.hasSuffix(" 开始，仅记录时长，不计入收入。") {
            let value = key
                .replacingOccurrences(of: "从 ", with: "")
                .replacingOccurrences(of: " 开始，仅记录时长，不计入收入。", with: "")
            switch language {
            case .zhHant: return "從 \(value) 開始，只記錄時長，不計入收入。"
            case .en: return "Started at \(value). Only duration is tracked; income is not added."
            case .ja: return "\(value) から開始。時間のみ記録し、収入には加算しません。"
            case .ko: return "\(value)에 시작했습니다. 시간만 기록하고 수입에는 더하지 않습니다."
            default: return nil
            }
        }
        if key.hasPrefix("默认从 "), key.hasSuffix(" 开始，可手动补录开始和结束时间。") {
            let value = key
                .replacingOccurrences(of: "默认从 ", with: "")
                .replacingOccurrences(of: " 开始，可手动补录开始和结束时间。", with: "")
            switch language {
            case .zhHant: return "預設從 \(value) 開始，可手動補錄開始和結束時間。"
            case .en: return "Defaults to \(value). You can manually add start and end times."
            case .ja: return "デフォルトは \(value) 開始。開始時刻と終了時刻は手動で補記できます。"
            case .ko: return "기본 시작 시간은 \(value)입니다. 시작 및 종료 시간을 직접 추가할 수 있습니다."
            default: return nil
            }
        }
        if key.hasSuffix("分") || key.hasSuffix("秒") {
            return durationTranslation(key, language: language)
        }
        if key.hasPrefix("一键收工，补齐今日剩余 ") {
            let amount = key
                .replacingOccurrences(of: "一键收工，补齐今日剩余 ", with: "")
                .replacingOccurrences(of: "。", with: "")
            switch language {
            case .zhHant: return "一鍵收工，補齊今日剩餘 \(amount)。"
            case .en: return "Clock out early and collect today's remaining \(amount)."
            case .ja: return "早退して、本日の残り \(amount) をまとめて獲得。"
            case .ko: return "조기 퇴근하고 오늘 남은 \(amount)을 바로 받습니다."
            default: return nil
            }
        }
        if key.hasPrefix("刚才摸鱼 "), key.contains("，公司为你的快乐支付了 ") {
            let text = key.replacingOccurrences(of: "。", with: "")
            let parts = text
                .replacingOccurrences(of: "刚才摸鱼 ", with: "")
                .components(separatedBy: "，公司为你的快乐支付了 ")
            guard parts.count == 2 else { return nil }
            switch language {
            case .zhHant: return "剛才摸魚 \(traditionalized(parts[0]))，公司為你的快樂支付了 \(parts[1])。"
            case .en: return "That break lasted \(parts[0]); the company paid \(parts[1]) for your joy."
            case .ja: return "さっきの休憩は \(parts[0])。その楽しさに会社が \(parts[1]) 支払いました。"
            case .ko: return "방금 휴식은 \(parts[0])였고, 회사가 그 즐거움에 \(parts[1])을 지급했습니다."
            default: return nil
            }
        }
        return nil
    }

    private static func fallbackTranslation(_ key: String, language: AppLanguage) -> String? {
        switch language {
        case .zhHant:
            return traditionalized(key)
        default:
            return nil
        }
    }

    private static func localizedPeriodPhrase(period: String, zhHantSuffix: String, enSuffix: String, jaSuffix: String, koSuffix: String, language: AppLanguage) -> String? {
        switch language {
        case .zhHant:
            return "\(traditionalized(period))\(zhHantSuffix)"
        case .en:
            return "\(periodName(period, language: .en)) \(enSuffix)"
        case .ja:
            return "\(periodName(period, language: .ja))\(jaSuffix)"
        case .ko:
            return "\(periodName(period, language: .ko))\(koSuffix)"
        case .system, .zhHans:
            return nil
        }
    }

    private static func periodName(_ value: String, language: AppLanguage) -> String {
        switch (value, language) {
        case ("今日", .en): return "Today"
        case ("本月", .en): return "Monthly"
        case ("本年", .en), ("今年", .en): return "Yearly"
        case ("今日", .ja): return "今日"
        case ("本月", .ja): return "今月"
        case ("本年", .ja), ("今年", .ja): return "今年"
        case ("今日", .ko): return "오늘"
        case ("本月", .ko): return "이번 달"
        case ("本年", .ko), ("今年", .ko): return "올해"
        default:
            return value
        }
    }

    private static func durationTranslation(_ key: String, language: AppLanguage) -> String? {
        if key.hasSuffix("秒"), let seconds = key.dropLast().split(separator: "分").last {
            if key.contains("分") {
                let parts = key.dropLast().split(separator: "分")
                guard parts.count == 2 else { return nil }
                switch language {
                case .zhHant: return "\(parts[0])分\(parts[1])秒"
                case .en: return "\(parts[0])m \(parts[1])s"
                case .ja: return "\(parts[0])分\(parts[1])秒"
                case .ko: return "\(parts[0])분 \(parts[1])초"
                default: return nil
                }
            }
            switch language {
            case .zhHant: return "\(seconds)秒"
            case .en: return "\(seconds)s"
            case .ja: return "\(seconds)秒"
            case .ko: return "\(seconds)초"
            default: return nil
            }
        }
        return nil
    }

    private static func controlAccessibilityTranslation(_ key: String, language: AppLanguage) -> String? {
        let pairs = [
            ("当前主题 ", "目前主題 ", "Current theme: ", "現在のテーマ：", "현재 테마: "),
            ("切换主题 ", "切換主題 ", "Switch theme: ", "テーマを切り替え：", "테마 전환: "),
            ("当前 App 图标 ", "目前 App 圖示 ", "Current App icon: ", "現在のAppアイコン：", "현재 앱 아이콘: "),
            ("切换 App 图标 ", "切換 App 圖示 ", "Switch App icon: ", "Appアイコンを切り替え：", "앱 아이콘 전환: ")
        ]
        guard let match = pairs.first(where: { key.hasPrefix($0.0) }) else { return nil }
        let name = key.replacingOccurrences(of: match.0, with: "")
        switch language {
        case .zhHant: return match.1 + traditionalized(name)
        case .en: return match.2 + name
        case .ja: return match.3 + name
        case .ko: return match.4 + name
        default: return nil
        }
    }

    private static func traditionalized(_ key: String) -> String {
        var value = key
        let replacements = [
            ("跟随", "跟隨"), ("系统", "系統"), ("语言", "語言"), ("设置", "設定"), ("薪资", "薪資"),
            ("时薪", "時薪"), ("金额", "金額"), ("周", "週"), ("元气", "元氣"), ("招财", "招財"),
            ("经典", "經典"), ("开薪", "開薪"), ("连接", "連接"), ("请求", "請求"), ("权限", "權限"),
            ("开启", "開啟"), ("临时", "暫時"), ("钱包", "錢包"), ("暂停", "暫停"), ("到账", "入帳"),
            ("收入", "收入"), ("下线", "下線"), ("首页", "首頁"), ("统计", "統計"), ("锁屏", "鎖定畫面"),
            ("灵动岛", "動態島"), ("当前", "目前"), ("实时活动", "即時活動"), ("工作时间", "工作時間"),
            ("输入", "輸入"), ("保存", "儲存"), ("稍后", "稍後"), ("类型", "類型"), ("计薪", "計薪"),
            ("每日", "每日"), ("预计", "預估"), ("选择", "選擇"), ("已赚", "已賺"), ("进度", "進度"),
            ("倒计时", "倒數"), ("继续", "繼續"), ("加班", "加班"), ("摸鱼", "摸魚"), ("时长", "時長"),
            ("换算", "換算"), ("火锅", "火鍋"), ("明细", "明細"), ("等效", "等效"), ("状态", "狀態"),
            ("目标", "目標"), ("剩余", "剩餘"), ("权益", "權益"), ("查看", "查看"), ("编辑", "編輯"),
            ("隐私", "隱私"), ("密码", "密碼"), ("提醒", "提醒"), ("主题", "主題"), ("数据", "資料"),
            ("同步", "同步"), ("帮助", "幫助"), ("反馈", "回饋"), ("小组件", "小工具"), ("桌面", "桌面"),
            ("买断", "買斷"), ("图标", "圖示"), ("本地", "本機"), ("上传", "上傳"), ("恢复", "恢復"),
            ("政策", "政策"), ("条款", "條款"), ("账号", "帳號"), ("账户", "帳戶"), ("昵称", "暱稱"),
            ("用户标识", "使用者識別碼"), ("操作", "操作"), ("退出", "登出"), ("删除", "刪除"),
            ("头像", "頭像"), ("个性签名", "個性簽名"), ("资料", "資料"), ("解锁", "解鎖"),
            ("订阅", "訂閱"), ("价格", "價格"), ("加载", "載入"), ("任务板", "任務板"), ("立即", "立即"),
            ("生效", "生效"), ("换机", "換機"), ("自由切换", "自由切換"), ("上线", "上線"), ("装饰", "裝飾"),
            ("继续", "繼續"), ("打开", "開啟"), ("失败", "失敗"), ("暂时", "暫時"), ("默认", "預設"),
            ("关闭", "關閉"), ("确认", "確認"), ("无法", "無法"), ("未知", "未知"), ("本机", "本機"),
            ("计算", "計算"), ("小时", "小時"), ("服务", "服務"), ("支持", "支援")
        ]
        for (source, target) in replacements {
            value = value.replacingOccurrences(of: source, with: target)
        }
        return value
    }

