        "实时活动、隐私保护、同步、午休与主题资产一次解锁。": "라이브 액티비티, 개인정보 보호, 동기화, 점심 시간, 테마 리소스를 한 번에 엽니다.",
        "同步、灵动岛、密码、午休和主题，一次解锁。": "동기화, 다이내믹 아일랜드, 비밀번호, 점심 시간, 테마를 한 번에 엽니다.",
        "同步、锁屏、密码、午休、主题和未来新功能全部打包。": "동기화, 잠금 화면, 비밀번호, 점심 시간, 테마, 향후 기능이 모두 포함됩니다.",
        "主题、App 图标和整套视觉装饰，开通后立即可切换。": "테마, 앱 아이콘, 전체 시각 장식은 활성화 후 바로 전환할 수 있습니다.",
        "主题资产与未来新功能": "테마 리소스와 향후 기능",
        "主题控制 App、小组件、锁屏和灵动岛的视觉风格；App 图标可以单独选择，不和主题绑定。": "테마는 앱, 위젯, 잠금 화면, 다이내믹 아일랜드의 시각 스타일을 제어합니다. 앱 아이콘은 테마와 별도로 선택할 수 있습니다.",
        "系统实时活动看收入": "시스템 라이브 액티비티에서 수입 보기",
        "多设备恢复设置": "여러 기기에서 설정 복원",
        "4 位密码保护": "4자리 비밀번호 보호",
        "4 位密码守隐私": "4자리 비밀번호로 개인정보 보호",
        "暂停计薪更准确": "급여 계산을 멈춰 더 정확하게",
        "开通后可设置午休暂停计薪，让今日收入和进度更贴近实际。": "활성화 후 점심 시간 급여 계산을 멈춰 오늘 수입과 진행률을 더 실제에 가깝게 만들 수 있습니다.",
        "开启后午休不会计入今日已赚和进度。": "켜면 점심 시간은 오늘 번 금액과 진행률에 포함되지 않습니다.",
        "保存后首页会这样算": "저장 후 홈에서 이렇게 계산합니다",
        "可自由选择周一到周日任意计薪日；未选中的日期首页会显示休息日。": "월요일부터 일요일까지 원하는 급여 계산일을 선택할 수 있습니다. 선택하지 않은 날은 홈에서 휴일로 표시됩니다.",
        "默认 21.75 天，适合多数固定月薪场景；时薪模式会按每日工作时长计算。": "기본값은 21.75일이며 대부분의 고정 월급 상황에 적합합니다. 시급 모드는 일일 근무 시간으로 계산합니다.",
        "薪资金额要大于 0，钱包才知道怎么回血。": "급여 금액은 0보다 커야 합니다.",
        "月计薪天数要大于 0。": "월 급여 일수는 0보다 커야 합니다.",
        "至少选择一天作为计薪日。": "급여 계산일을 최소 하루 선택하세요.",
        "下班时间必须晚于上班时间。": "퇴근 시간은 출근 시간보다 늦어야 합니다.",
        "午休时间需要落在上班和下班之间。": "점심 시간은 출근과 퇴근 사이여야 합니다.",
        "午休结束时间必须晚于午休开始时间。": "점심 종료 시간은 시작 시간보다 늦어야 합니다.",
        "查看账号信息、退出登录和删除账号": "계정 정보, 로그아웃, 계정 삭제 보기",
        "账号信息、退出和删除都在这里。": "계정 정보, 로그아웃, 삭제가 여기에 있습니다.",
        "退出后，本机数据会保留；需要同步或恢复时可以再次连接 Apple ID。": "로그아웃 후에도 로컬 데이터는 유지됩니다. 동기화나 복원이 필요하면 Apple ID를 다시 연결하세요.",
        "这会退出 Apple ID，并删除本机保存的数据；若已连接 iCloud，也会尝试删除开薪的 iCloud 私有库记录。此操作不能撤销。": "Apple ID에서 로그아웃하고 이 기기에 저장된 데이터를 삭제합니다. iCloud가 연결되어 있으면 ClockJoy의 개인 iCloud 기록도 삭제를 시도합니다. 이 작업은 되돌릴 수 없습니다.",
        "删除账号与数据？": "계정과 데이터를 삭제할까요?",
        "删除账号会清空本机数据，并尝试删除 iCloud 私有库里的开薪记录。": "계정을 삭제하면 로컬 데이터를 지우고 iCloud 개인 데이터베이스의 ClockJoy 기록 삭제를 시도합니다.",
        "删除本机数据": "기기 데이터 삭제",
        "清除本机数据？": "기기 데이터를 삭제할까요?",
        "这会删除本机保存的薪资、记录、目标和设置，并退出 Apple ID。若曾同步到 iCloud，云端数据不会被删除，可在之后重新连接并恢复。": "이 기기의 급여, 기록, 목표, 설정을 삭제하고 Apple ID에서 로그아웃합니다. 이전에 동기화한 iCloud 데이터는 남아 나중에 다시 연결해 복원할 수 있습니다.",
        "本机数据已删除。若此前同步过，重新连接 Apple ID 后可从 iCloud 恢复。": "기기 데이터를 삭제했습니다. 이전에 동기화한 데이터는 Apple ID를 다시 연결해 iCloud에서 복원할 수 있습니다.",
        "仅删除这台设备上的数据，不会删除 iCloud 记录。": "이 기기의 데이터만 삭제하며 iCloud 기록은 삭제하지 않습니다.",
        "已退出 Apple ID，本机数据仍会继续保存。": "Apple ID에서 로그아웃했습니다. 로컬 데이터는 계속 저장됩니다.",
        "管理 Apple ID": "Apple ID 관리",
